'use strict';
let db = null, csrf = '', view = 'overview', query = '', statusFilter = '', selected = null;
const app = document.querySelector('#app'), dialog = document.querySelector('#dialog');
const esc = x => String(x ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const euro = n => new Intl.NumberFormat('de-AT',{style:'currency',currency:'EUR'}).format((n||0)/100);
const dec = n => ((n||0)/100).toFixed(2).replace('.',',');
const day = s => s ? new Date(s.slice(0,10)+'T12:00:00').toLocaleDateString('de-AT') : '—';
const today = () => {const d=new Date(); return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
const customer = id => db.customers.find(c=>c.id===Number(id));
const contract = id => db.contracts.find(c=>c.id===Number(id));
const referrer = id => db.referrers.find(c=>c.id===Number(id));
const customerRelationship = id => db.customer_relationships.find(r=>r.id===Number(id));
const full = c => c ? ((c.customer_type==='legal'?c.company:[c.first_name,c.last_name].filter(Boolean).join(' '))||'—') : '—';
const customerKind = c => c?.customer_type==='legal'?'Juristische Person':'Natürliche Person';
const initials = c => (c?.customer_type==='legal'?(c.company||'').split(/\s+/).slice(0,2):[c?.first_name,c?.last_name]).filter(Boolean).map(x=>x[0]).join('').toUpperCase();
const freq = n => ({1:'jährlich',2:'halbjährlich',4:'vierteljährlich',12:'monatlich'}[n]);
const basisName = b => ({agency:'Eingegangene Agenturprovision',premium:'Prämie laut Vereinbarung',fixed:'Fixbetrag'}[b]);
const icon = (name) => {const paths={overview:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',customers:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',contracts:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z M14 2v6h6 M8 13h8 M8 17h6',referrers:'M9 12l2 2 4-4 M12 3l9 4v6c0 5-9 9-9 9s-9-4-9-9V7z',commissions:'M12 2v20 M17 5H9a4 4 0 0 0 0 8h6a3 3 0 0 1 0 6H6',settlements:'M4 3h16v18l-4-2-4 2-4-2-4 2z M8 8h8 M8 12h8',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.contracts}"/></svg>`;};
const button = (label,action,id='',cls='secondary')=>`<button class="${cls}" data-action="${action}" data-id="${esc(id)}">${label}</button>`;
const deleteButton = (table,id,label='Löschen')=>`<button type="button" class="text-button delete-action" data-action="delete-record" data-table="${esc(table)}" data-id="${esc(id)}">${label}</button>`;
const documentActions = d=>`<a class="text-button" href="/api/documents/${d.id}">Herunterladen ↓</a><button type="button" class="text-button" data-action="rename-document" data-id="${d.id}">Umbenennen</button>${deleteButton('documents',d.id)}`;
const dashboardScroll = (label,body)=>`<div class="dashboard-card-body" role="region" aria-label="${esc(label)}" tabindex="0">${body}</div>`;
const badge = value=>`<span class="badge ${['Aktiv','Erledigt'].includes(value)?'green':['Storniert','Aufgehoben'].includes(value)?'red':''}">${esc(value)}</span>`;
const empty = (title,text,action='',label='',id='')=>`<div class="empty"><div class="empty-icon">${icon('contracts')}</div><h3>${title}</h3><p>${text}</p>${action?button(label,action,id,'primary'):''}</div>`;
const table = (heads,rows)=>`<div class="table-wrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.join('')}</tbody></table></div>`;
function notice(text){const el=document.querySelector('#toast');el.textContent=text;el.classList.add('show');clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.classList.remove('show'),4500);}
async function api(path,data){const res=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',headers:data===undefined?{}:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:data===undefined?undefined:JSON.stringify(data)});if(!res.ok){const body=await res.json();if(res.status===401&&!['login','setup'].includes(path)){dialog.close();db=null;await init();}throw new Error(body.error||'Anfrage fehlgeschlagen.');}return res.json();}
async function reload(){db=await api('state');render();}
async function init(){try{const session=await api('session');if(!session.authenticated){renderLogin(session.setup_required);return;}csrf=session.csrf;await reload();}catch(e){app.innerHTML=`<main class="auth"><h1>CRM nicht erreichbar</h1><p>${esc(e.message)}</p>${button('Erneut versuchen','retry')}</main>`;}}
function renderLogin(setup){app.innerHTML=`<main class="auth"><div class="brandmark">B<span>.</span></div><div class="eyebrow">VERSICHERUNGSAGENTUR · LOKAL</div><h1>${setup?'Dein CRM einrichten':'Willkommen zurück'}</h1><p>${setup?'Lege den Agenturnamen und dein persönliches Passwort fest. Deine Daten bleiben auf diesem Rechner.':'Melde dich an, um deine Kunden und Verträge zu verwalten.'}</p><form id="auth-form" data-setup="${setup}">${setup?field('agency_name','Name der Agentur','Versicherungsagentur Bogaards','text',true):''}${field('password',setup?'Passwort festlegen (mind. 12 Zeichen)':'Passwort','','password',true)}${setup?field('confirmation','Passwort wiederholen','','password',true):''}<div class="form-error" role="alert"></div><button class="primary wide">${setup?'CRM einrichten':'Anmelden'}</button></form><small>Nur auf diesem Rechner erreichbar · SQL-Datenbank</small></main>`;}
const navigation=[['overview','Übersicht'],['imports','Import'],['customers','Kunden'],['contracts','Versicherungsverträge'],['claims','Schäden'],['referrers','Tippgeber'],['commissions','Provisionen'],['settlements','Abrechnungen'],['settings','Einstellungen']];
function render(){if(!db)return;app.innerHTML=`<aside><div class="brand"><div class="brandmark">B<span>.</span></div><div>Agentur CRM<small>${esc(db.settings.agency_name)}</small></div></div><nav aria-label="Hauptnavigation">${navigation.map(([id,label])=>`<button data-action="nav" data-id="${id}" class="nav-item ${view===id?'active':''}" ${view===id?'aria-current="page"':''}>${icon(id)}<span>${label}</span>${id==='customers'?`<small>${db.customers.filter(c=>!c.archived).length}</small>`:''}</button>`).join('')}</nav><div class="aside-bottom"><span class="local-dot"></span> Lokal auf deinem Rechner<small>Alle Beträge in EUR</small>${button('Abmelden','logout','','text-button')}</div></aside><div class="workspace"><header><div class="breadcrumb">Agentur <span>/</span> ${navigation.find(x=>x[0]===view)[1]}</div><div class="header-right"><span>${new Date().toLocaleDateString('de-AT',{day:'numeric',month:'long',year:'numeric'})}</span><div class="avatar">PB</div>${button('Abmelden','logout','','text-button')}</div></header><main id="main" tabindex="-1">${content()}</main><footer>Versicherungsagentur CRM <span>Lokale Version 1.0</span></footer></div>`;}
function pagehead(title,sub,actions=''){return `<div class="pagehead"><div><div class="eyebrow">DEIN AGENTURBÜRO</div><h1>${title}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;}
function tools(placeholder,filter=''){return `<div class="toolbar"><label class="search"><span>⌕</span><input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${esc(query)}"></label>${filter}</div>`;}
function content(){switch(view){case'overview':return overview();case'imports':return importsView();case'customers':return customersView();case'contracts':return contractsView();case'claims':return claimsView();case'referrers':return referrersView();case'commissions':return commissionsView();case'settlements':return settlementsView();case'settings':return settingsView();}}
function nextBirthday(value){
 if(!value)return null;
 const [year,month,dayOfMonth]=value.split('-').map(Number),now=new Date();
 const start=new Date(now.getFullYear(),now.getMonth(),now.getDate());
 let next=new Date(now.getFullYear(),month-1,dayOfMonth);
 if(next<start)next=new Date(now.getFullYear()+1,month-1,dayOfMonth);
 return {date:next,days:Math.round((next-start)/86400000),age:next.getFullYear()-year};
}
function birthdayDashboard(){
 const rows=db.customers.filter(c=>!c.archived&&c.customer_type!=='legal'&&c.birthday).map(c=>({customer:c,...nextBirthday(c.birthday)})).filter(x=>x.days<=30).sort((a,b)=>a.days-b.days);
 const body=rows.length?rows.map(x=>`<button class="deadline" data-action="customer" data-id="${x.customer.id}"><span class="date-box">${x.date.toLocaleDateString('de-AT',{day:'2-digit',month:'2-digit'})}</span><span><strong>${esc(full(x.customer))}</strong><small>${x.days===0?'Heute':x.days===1?'Morgen':'In '+x.days+' Tagen'} · ${x.age}. Geburtstag</small></span>${x.days===0?'<span class="badge green">Heute</span>':''}</button>`).join(''):empty('Keine aktuellen Geburtstage','In den nächsten 30 Tagen steht kein hinterlegter Kundengeburtstag an.');
 return `<section class="card birthdays"><div class="sectionhead"><h2>Geburtstage</h2><span class="badge">Nächste 30 Tage</span></div>${dashboardScroll('Geburtstage der nächsten 30 Tage',body)}</section>`;
}
function pendingContractsDashboard(){
 const pending=db.contracts.filter(c=>c.status==='Beantragt').sort((a,b)=>a.start_date.localeCompare(b.start_date));
 const body=pending.length?pending.map(c=>{
  const documents=db.documents.filter(d=>d.contract_id===c.id&&!d.claim_id).length;
  return `<button class="deadline" data-action="edit-contract" data-id="${c.id}"><span class="date-box">${day(c.start_date)}</span><span><strong>${esc(full(customer(c.customer_id)))}</strong><small>${esc(c.insurer)} · ${esc(c.line)} · ${esc(c.policy_number)}<br>${documents} Vertragsdokument${documents===1?'':'e'}</small></span><span class="badge ${documents?'':'red'}">${documents?'Polizze prüfen':'Keine Dokumente'}</span></button>`;
 }).join(''):empty('Keine beantragten Verträge','Beantragte Verträge erscheinen hier, bis du ihren Status änderst.');
 return `<section class="card dashboard-list-card"><div class="sectionhead"><h2>Beantragte Verträge · Polizzen-Evidenz</h2>${button('Alle Verträge →','nav','contracts','text-button')}</div>${dashboardScroll('Beantragte Verträge und Polizzen-Evidenz',body)}</section>`;
}
function overview(){
 const active=db.contracts.filter(c=>c.status==='Aktiv');
 const openClaims=db.claims.filter(claimIsOpen);
 const unpaid=db.commissions.filter(c=>!c.voided&&!db.settlements.find(s=>s.id===c.settlement_id)?.paid_at);
 const stats=[['Kunden',db.customers.filter(c=>!c.archived).length,'Aktive Kundenakten','customers'],['Aktive Verträge',active.length,'Im Versicherungsbestand','contracts'],['Offene Schäden',openClaims.length,'In Bearbeitung oder Evidenz','claims'],['Jahresprämien',euro(active.reduce((s,c)=>s+c.premium_cents*c.frequency,0)),'Hochgerechnet aus aktiven Verträgen','contracts'],['Tippgeber offen',euro(unpaid.reduce((s,c)=>s+c.amount_cents,0)),'Unabgerechnet oder noch nicht erledigt','commissions']];
 const deadline=new Date();deadline.setDate(deadline.getDate()+90);const end=deadline.toISOString().slice(0,10);
 const due=db.contracts.filter(c=>['Aktiv','Beantragt'].includes(c.status)&&c.notice_date&&c.notice_date<=end).sort((a,b)=>a.notice_date.localeCompare(b.notice_date));
 return pagehead('Deine Agentur im Überblick','Kunden, Verträge, Schäden und Provisionen an einem Ort.',button('+ Neuer Kunde','new-customer','','primary')+button('+ Neuer Schaden','new-claim','','secondary'))+
 `<div class="stats">${stats.map(([title,value,desc,id])=>`<button class="stat" data-action="nav" data-id="${id}"><div class="stat-top">${title}${icon(id)}</div><strong>${value}</strong><small>${desc}</small></button>`).join('')}</div>`+
 `<div class="dashboard-grid dashboard-evidence">${claimsDashboard()}${pendingContractsDashboard()}</div>`+
 `<div class="dashboard-grid dashboard-three"><section class="card recent-customer-card"><div class="sectionhead"><h2>Zuletzt angelegte Kunden</h2>${button('Alle Kunden →','nav','customers','text-button')}</div>${dashboardScroll('Zuletzt angelegte Kunden',db.customers.some(c=>!c.archived)?recentCustomerList(db.customers.filter(c=>!c.archived).slice(0,3)):empty('Platz für deine Kunden','Beginne mit deiner ersten Kundenakte.','new-customer','+ Kunde anlegen'))}</section><section class="card deadlines"><div class="sectionhead"><h2>Anstehende Kündigungstermine</h2><span class="badge">90 Tage</span></div>${dashboardScroll('Anstehende Kündigungstermine',due.length?due.map(c=>`<button class="deadline" data-action="edit-contract" data-id="${c.id}"><span class="date-box">${day(c.notice_date)}</span><span><strong>${esc(full(customer(c.customer_id)))}</strong><small>${esc(c.insurer)} · ${esc(c.line)} · ${esc(c.ownership||'Eigen')}</small></span>${c.notice_date<today()?'<span class="badge red">Überfällig</span>':''}</button>`).join(''):empty('Keine Kündigungstermine offen','Hier erscheinen überfällige und in den nächsten 90 Tagen anstehende Kündigungstermine.'))}</section>${birthdayDashboard()}</div><section class="card dashboard-list-card"><div class="sectionhead"><h2>Letzte Provisionsbuchungen</h2>${button('+ Provision buchen','new-commission','','secondary')}</div>${dashboardScroll('Letzte Provisionsbuchungen',commissionTable(db.commissions.slice(0,5)))}</section>`;
}
function recentCustomerList(rows){
 return `<div class="recent-customers">${rows.map(c=>{
  const extra=c.customer_type==='legal'?[c.first_name,c.last_name].filter(Boolean).join(' '):c.company;
  const contracts=db.contracts.filter(v=>v.customer_id===c.id).length;
  return `<article class="recent-customer"><div class="recent-customer-top"><button class="name-link" data-action="customer" data-id="${c.id}"><span class="initials">${esc(initials(c))}</span><strong>${esc(full(c))}</strong></button>${badge(c.archived?'Archiviert':'Aktiv')}</div><div class="recent-customer-meta"><span>K-${String(c.id).padStart(5,'0')} · ${customerKind(c)}</span><span>${contracts} ${contracts===1?'Vertrag':'Verträge'}</span></div>${extra?`<div class="recent-customer-extra">${c.customer_type==='legal'?'Kontaktperson: ':'Firma: '}${esc(extra)}</div>`:''}<div class="recent-customer-contact">${esc(c.email||'Keine E-Mail')}${c.phone?` · ${esc(c.phone)}`:''}</div></article>`;
 }).join('')}</div>`;
}
function customerTable(rows){return table(['Kunde','Kontakt','Verträge','Status',''],rows.map(c=>`<tr><td><button class="name-link" data-action="customer" data-id="${c.id}"><span class="initials">${esc(initials(c))}</span><span>${esc(full(c))}<small>K-${String(c.id).padStart(5,'0')} · ${customerKind(c)}${c.customer_type==='legal'&&c.first_name?` · Kontakt: ${esc([c.first_name,c.last_name].filter(Boolean).join(' '))}`:c.customer_type!=='legal'&&c.company?' · '+esc(c.company):''}</small></span></button></td><td>${esc(c.email||'—')}<small>${esc(c.phone)}</small></td><td>${db.contracts.filter(v=>v.customer_id===c.id).length}</td><td>${badge(c.archived?'Archiviert':'Aktiv')}</td><td class="row-actions">${button('Öffnen →','customer',c.id,'text-button')}${deleteButton('customers',c.id)}</td></tr>`));}
function customersView(){if(selected)return customerDetail(Number(selected));const rows=db.customers.filter(c=>(!statusFilter||String(c.archived)===statusFilter)&&[full(c),c.company,c.email,c.phone,c.id].join(' ').toLowerCase().includes(query.toLowerCase()));return pagehead('Kunden','Deine Kundenakten und die zugehörigen Versicherungen.',button('+ Neuer Kunde','new-customer','','primary'))+`<section class="card">${tools('Name, E-Mail oder Kundennummer suchen',select('status-filter','', [['','Alle Kunden'],['0','Aktiv'],['1','Archiviert']],statusFilter))}<div id="results">${rows.length?customerTable(rows):empty('Keine Kunden gefunden','Lege einen Kunden an oder passe die Suche an.')}</div></section>`;}
const relationshipPresets=[
 ['spouse','Ehepartner/in','Ehepartner/in','Ehepartner/in'],['daughter','Tochter','Elternteil','Tochter'],['son','Sohn','Elternteil','Sohn'],
 ['parent_daughter','Elternteil','Tochter','Elternteil einer Tochter'],['parent_son','Elternteil','Sohn','Elternteil eines Sohnes'],
 ['manager','Geschäftsführer/in','Unternehmen','Geschäftsführer/in'],['company_manager','Unternehmen','Geschäftsführer/in','Geschäftsführung'],
 ['procurist','Prokurist/in','Unternehmen','Prokurist/in'],['company_procurist','Unternehmen','Prokurist/in','Prokura'],
 ['employee','Mitarbeiter/in','Arbeitgeber','Mitarbeiter/in'],['employer','Arbeitgeber','Mitarbeiter/in','Mitarbeitende'],
 ['managed_property','Hausverwaltung','Verwaltete Immobilie','Verwaltete Immobilie'],['property_manager','Verwaltete Immobilie','Hausverwaltung','Hausverwaltung'],
 ['subsidiary','Muttergesellschaft','Tochterfirma','Tochterfirma'],['parent_company','Tochterfirma','Muttergesellschaft','Muttergesellschaft'],
 ['sister_company','Schwesterfirma','Schwesterfirma','Schwesterfirma']
];
function relationshipFields(values={},embedded=false){const match=relationshipPresets.find(([,a,b])=>a===values.relationship&&b===values.reciprocal_relationship),preset=values.relationship?(match?.[0]||'custom'):relationshipPresets[0][0];const options=[...relationshipPresets.map(([key,,,label])=>[key,label]),['custom','Andere Verbindung']];return `${select('relationship_template','Art der Verbindung',options,preset,true)}${field('relationship','Rolle dieses Kunden',values.relationship,'text',true)}${field('reciprocal_relationship','Rolle des verknüpften Kunden',values.reciprocal_relationship,'text',true)}${textarea(embedded?'relationship_notes':'notes','Notiz zur Verbindung',values.notes)}`;}
function relationshipView(r,currentId){
 const forward=r.customer_id===Number(currentId);
 return {id:r.id,version:r.version,customer_id:Number(currentId),related_customer_id:forward?r.related_customer_id:r.customer_id,
         relationship:forward?r.relationship:r.reciprocal_relationship,
         reciprocal_relationship:forward?r.reciprocal_relationship:r.relationship,notes:r.notes};
}
function relationshipList(currentId){
 const rows=db.customer_relationships.filter(r=>r.customer_id===Number(currentId)||r.related_customer_id===Number(currentId)).map(r=>relationshipView(r,currentId));
 return rows.length?`<div class="relationship-list">${rows.map(r=>{const other=customer(r.related_customer_id);return `<article class="relationship-item"><button class="name-link" data-action="customer" data-id="${other.id}"><span class="initials">${esc(initials(other))}</span><span><strong>${esc(full(other))}</strong><small>${esc(r.reciprocal_relationship)} · ${esc(customerKind(other))}</small></span></button><div class="relationship-actions">${button('Bearbeiten','edit-relationship',r.id,'text-button')} ${deleteButton('customer_relationships',r.id)}</div>${r.notes?`<p>${esc(r.notes)}</p>`:''}</article>`;}).join('')}</div>`:empty('Noch keine Verbindungen','Verbinde diesen Kunden mit Familienangehörigen, Personen oder Unternehmen.','new-relationship','+ Verbindung anlegen',currentId);
}
function editRelationship(r={},currentId=selected){
 if(!r.id&&!db.customers.some(c=>c.id!==Number(currentId)&&!c.archived)){notice('Lege zuerst einen weiteren Kunden oder eine Firma an.');return;}
 const oriented=r.id?relationshipView(r,currentId):{customer_id:Number(currentId),related_customer_id:'',relationship:'',reciprocal_relationship:'',notes:''};
 modal(r.id?'Verbindung bearbeiten':'Kunden verbinden',`<input type="hidden" name="customer_id" value="${oriented.customer_id}">${customerPicker(oriented.related_customer_id,'related_customer_id','Verknüpfter Kunde')}<div class="form-grid">${relationshipFields(oriented)}</div><p class="hint">Die Verbindung wird automatisch in beiden Kundenakten angezeigt.</p>`,'customer_relationships',{id:r.id,version:r.version});
 setupCustomerPicker(oriented.related_customer_id,'related_customer_id',currentId);updateRelationshipTemplate(!r.id);
}
function updateRelationshipTemplate(replace=true){const f=document.querySelector('#editor');if(!f||!f.elements.relationship_template)return;const custom=f.elements.relationship_template.value==='custom',preset=relationshipPresets.find(([key])=>key===f.elements.relationship_template.value);if(preset&&replace){f.elements.relationship.value=preset[1];f.elements.reciprocal_relationship.value=preset[2];}f.elements.relationship.closest('label').hidden=!custom;f.elements.reciprocal_relationship.closest('label').hidden=!custom;f.elements.relationship.required=custom;f.elements.reciprocal_relationship.required=custom;}
function customerDetail(id){
 const c=customer(id);if(!c){selected=null;return customersView();}
 const contracts=db.contracts.filter(v=>v.customer_id===id),docs=db.documents.filter(d=>d.customer_id===id&&!d.claim_id),claims=db.claims.filter(item=>item.customer_id===id);
 return `${button('← Zur Kundenliste','back','','text-button')}`+pagehead(esc(full(c)),`K-${String(c.id).padStart(5,'0')} · ${customerKind(c)}`,`<a class="secondary" href="/api/customer-overviews/${c.id}" target="_blank" rel="noopener">Vertragsübersicht / PDF ↗</a>`+button('Kunde bearbeiten','edit-customer',c.id)+button('+ Vertrag','new-contract',c.id)+button('+ Kfz-Vertrag','new-kfz-contract',c.id)+button('+ Schaden','new-claim-customer',c.id,'primary')+deleteButton('customers',c.id))+
 `<div class="detail-grid"><div><section class="card profile"><h2>Kundenakte ${badge(c.archived?'Archiviert':'Aktiv')}</h2><dl>${c.customer_type==='legal'?`<dt>Kontaktperson</dt><dd>${esc([c.first_name,c.last_name].filter(Boolean).join(' ')||'—')}</dd>`:c.company?`<dt>Firma</dt><dd>${esc(c.company)}</dd>`:''}<dt>E-Mail</dt><dd>${esc(c.email||'—')}</dd><dt>Telefon</dt><dd>${esc(c.phone||'—')}</dd><dt>Adresse</dt><dd>${esc([c.address,c.postal_code+' '+c.city].filter(x=>x.trim()).join(', ')||'—')}</dd>${c.customer_type!=='legal'?`<dt>Geburtstag</dt><dd>${day(c.birthday)}</dd>`:''}</dl><h3>Notizen</h3><p class="preline">${esc(c.notes||'Noch keine Notizen.')}</p></section><section class="card"><div class="sectionhead"><h2>Verbindungen</h2>${button('+ Verbindung','new-relationship',c.id,'text-button')}</div>${relationshipList(c.id)}</section></div><div><section class="card"><div class="sectionhead"><h2>Versicherungsverträge</h2><span class="badge">${contracts.length}</span></div>${contractTable(contracts)}</section><section class="card"><div class="sectionhead"><h2>Schäden</h2>${button('+ Schaden anlegen','new-claim-customer',c.id)}</div>${claims.length?claimTable(claims):empty('Keine Schäden zu diesem Kunden','Ein Schaden kann direkt mit Kunde und optional mit Vertrag angelegt werden.')}</section><section class="card"><div class="sectionhead"><h2>Dokumente</h2>${button('+ Dokument ablegen','upload',c.id)}</div>${docs.length?table(['Dateiname','Zuordnung','Größe',''],docs.map(d=>`<tr><td>${esc(d.filename)}<small>${day(d.created_at)}</small></td><td>${esc(d.contract_id?contract(d.contract_id)?.policy_number:'Kundenakte')}</td><td>${(d.size/1024).toFixed(0)} KB</td><td class="row-actions">${documentActions(d)}</td></tr>`)):empty('Noch keine allgemeinen Dokumente','Polizzen, Anträge und weitere Unterlagen hier ablegen. Schadendokumente findest du in der jeweiligen Schadenakte.')}</section></div></div>`;
}
function contractTaxSummary(c){
 if(c.tax_cents==null)return 'Steuern nicht aufgeschlüsselt';
 if(!c.kfz_coverage)return 'inkl. '+euro(c.tax_cents)+' Steuer';
 return `<span class="tax-lines"><span>Versicherungssteuer</span><span>${euro(c.insurance_tax_cents||0)}</span><span>Motorbezogene Steuer</span><span>${euro(c.motor_tax_cents||0)}</span><span class="tax-total">Prämiensteuern gesamt</span><span class="tax-total">${euro(c.tax_cents)}</span>${c.vehicle_tax_cents==null?'':`<span class="tax-separate">Separate KfzSt: ${euro(c.vehicle_tax_cents)} / Monat</span>`}</span>`;
}
function contractTable(rows){return rows.length?table(['Versicherung / Polizze','Kunde','Herkunft','Prämie / Zahlung','Jahresprämie','Status',''],rows.map(c=>`<tr><td><strong>${esc(c.insurer)} · ${esc(c.line)}</strong><small>${esc(c.policy_number)}</small></td><td>${esc(full(customer(c.customer_id)))}</td><td><span class="badge ${c.ownership==='Eigen'?'green':''}">${esc(c.ownership||'Eigen')}</span></td><td>${euro(c.premium_cents)}<small>${freq(c.frequency)} · ${contractTaxSummary(c)}</small></td><td>${euro(c.premium_cents*c.frequency)}</td><td>${badge(c.status)}</td><td class="row-actions">${button('Bearbeiten','edit-contract',c.id,'text-button')}${button('Dokumente ('+db.documents.filter(d=>d.contract_id===c.id&&!d.claim_id).length+')','contract-documents',c.id,'text-button')}${button('Schaden anlegen','new-claim-contract',c.id,'text-button')}${deleteButton('contracts',c.id)}</td></tr>`)):empty('Noch keine Verträge','Lege einen Vertrag an und ordne ihn einem Kunden zu.');}
function contractsView(){const rows=db.contracts.filter(c=>(!statusFilter||c.status===statusFilter)&&[c.insurer,c.policy_number,c.line,c.ownership,full(customer(c.customer_id))].join(' ').toLowerCase().includes(query.toLowerCase()));return pagehead('Versicherungsverträge','Polizzen, Prämien und vereinbarte Tippgeber-Provisionen.',button('+ Kfz-Vertrag','new-kfz-contract','','primary')+button('+ Anderer Vertrag','new-contract','','secondary'))+`<section class="card">${tools('Kunde, Versicherer, Polizzennummer oder Herkunft suchen',select('status-filter','',[['','Alle Status'],...['Beantragt','Aktiv','Gekündigt','Storniert','Abgelaufen'].map(x=>[x,x])],statusFilter))}${contractTable(rows)}</section>`;}
function referrersView(){const rows=db.referrers.filter(r=>(r.name+' '+r.email).toLowerCase().includes(query.toLowerCase()));return pagehead('Tippgeber','Kontakte, Vereinbarungen und offene Vergütungen.',button('+ Neuer Tippgeber','new-referrer','','primary'))+`<section class="card">${tools('Tippgeber suchen')}${rows.length?table(['Tippgeber','Standardsatz','Verträge','Offene Provisionen','Status',''],rows.map(r=>`<tr><td><strong>${esc(r.name)}</strong><small>${esc(r.email||r.phone)}</small></td><td>${dec(r.rate_bp)} %</td><td>${db.contracts.filter(c=>c.referrer_id===r.id).length}</td><td>${euro(db.commissions.filter(m=>m.referrer_id===r.id&&!m.voided&&!db.settlements.find(s=>s.id===m.settlement_id)?.paid_at).reduce((a,m)=>a+m.amount_cents,0))}</td><td>${badge(r.archived?'Archiviert':'Aktiv')}</td><td class="row-actions">${button('Bearbeiten','edit-referrer',r.id,'text-button')}${deleteButton('referrers',r.id)}</td></tr>`)):empty('Dein Tippgeber-Netzwerk','Lege Kontakte und deren vereinbarte Provisionssätze an.','new-referrer','+ Tippgeber anlegen')}</section>`;}
function commissionStatus(m){return m.voided?'Aufgehoben':m.settlement_id?(db.settlements.find(s=>s.id===m.settlement_id)?.paid_at?'Erledigt':'Abgerechnet'):'Offen';}
function commissionTable(rows){return rows.length?table(['Buchung','Vertrag / Tippgeber','Berechnung','Provision','Status',''],rows.map(m=>`<tr><td><strong>${esc(m.reference)}</strong><small>${day(m.booking_date)} · ${esc(m.kind)}</small></td><td>${esc(contract(m.contract_id)?.policy_number)}<small>${esc(referrer(m.referrer_id)?.name)}</small></td><td>${euro(m.base_cents)}${m.basis!=='fixed'?' × '+dec(m.rate_bp)+' %':''}<small>${esc(basisName(m.basis))}</small></td><td><strong>${euro(m.amount_cents)}</strong></td><td>${badge(commissionStatus(m))}</td><td class="row-actions">${!m.voided&&!m.reverses_id&&!db.commissions.some(x=>x.reverses_id===m.id)?button(m.settlement_id?'Gegenbuchung':'Aufheben','reverse',m.id,'text-button'):''}${deleteButton('commissions',m.id)}</td></tr>`)):empty('Noch keine Provisionsbuchungen','Erfasse eine bestätigte Berechnungsbasis aus deiner Vereinbarung.');}
function commissionsView(){let rows=db.commissions.filter(m=>(!statusFilter||commissionStatus(m)===statusFilter)&&[m.reference,contract(m.contract_id)?.policy_number,referrer(m.referrer_id)?.name].join(' ').toLowerCase().includes(query.toLowerCase()));return pagehead('Provisionen','Jede Buchung mit eigener Referenz und festgehaltener Berechnungsbasis.',button('+ Provision buchen','new-commission','','primary'))+`<div class="info">Prämie und Agenturprovision sind unterschiedliche Grundlagen. Die Vereinbarung im Vertrag bestimmt, welche Basis verwendet wird. Buchungen erfolgen bewusst einzeln.</div><section class="card">${tools('Referenz, Polizze oder Tippgeber suchen',select('status-filter','',[['','Alle Status'],...['Offen','Abgerechnet','Erledigt','Aufgehoben'].map(x=>[x,x])],statusFilter))}${commissionTable(rows)}</section>`;}
function settlementsView(){return pagehead('Tippgeber-Abrechnungen','Offene Buchungen bündeln, Beleg speichern und Zahlung dokumentieren.',button('+ Abrechnung erstellen','new-settlement','','primary'))+`<section class="card">${db.settlements.length?table(['Abrechnung','Tippgeber','Zeitraum','Summe','Status',''],db.settlements.map(s=>`<tr><td><strong>${esc(s.number)}</strong><small>${day(s.created_at)}</small></td><td>${esc(referrer(s.referrer_id)?.name)}</td><td>${day(s.period_start)} – ${day(s.period_end)}</td><td><strong>${euro(s.total_cents)}</strong></td><td>${badge(s.paid_at?'Erledigt':'Offen')}</td><td class="row-actions"><a class="text-button" href="/api/statements/${s.id}" target="_blank" rel="noopener">Beleg / PDF ↗</a>${!s.paid_at?button('Zahlung / Ausgleich','pay',s.id,'text-button'):''}${deleteButton('settlements',s.id)}</td></tr>`)):empty('Noch keine Abrechnungen','Gebuchte Provisionen lassen sich je Tippgeber und Zeitraum abrechnen.')}</section><div class="info">Beim Löschen einer Abrechnung werden ihre Provisionen wieder offen. Gelöschte Belege können nur aus einer Sicherung wiederhergestellt werden.</div>`;}
function settingsView(){return pagehead('Einstellungen','Agenturdaten, Zugang und Datensicherung.')+`<div class="detail-grid"><section class="card padded"><h2>Agentur & Zugang</h2><form id="settings-form">${field('agency_name','Agenturname',db.settings.agency_name,'text',true)}${textarea('agency_address','Agenturanschrift',db.settings.agency_address)}<h3>Passwort ändern <small>(optional)</small></h3>${field('current_password','Bisheriges Passwort','','password')}${field('new_password','Neues Passwort (mind. 12 Zeichen)','','password')}<div class="form-error" role="alert"></div><button class="primary">Einstellungen speichern</button></form></section><section class="card padded"><h2>Datensicherung</h2><p>Erstellt eine vollständige Kopie der Datenbank und aller Dokumente. Die ZIP-Datei wird zusätzlich im Ordner Daten/Sicherungen gespeichert.</p>${button('Sicherung erstellen & herunterladen','backup','','primary')}<p class="muted">Die Sicherung enthält Kundendaten und den Passwort-Hash. Bewahre eine zusätzliche Kopie auf einem geschützten, getrennten Datenträger auf. Beim ersten Start des Tages wird ebenfalls eine Sicherung erstellt.</p><h3>Tabellen exportieren</h3><p>CSV für Übernahme und Auswertung. Geldbeträge werden exakt in Cent, Prozentsätze in Hundertstel-Prozent exportiert.</p><div class="export-links">${['customers','contracts','claims','referrers','commissions'].map((x,i)=>`<a class="secondary" href="/api/export/${x}">${['Kunden','Verträge','Schäden','Tippgeber','Provisionen'][i]} ↓</a>`).join('')}</div></section></div><section class="card"><div class="sectionhead"><h2>Änderungsprotokoll</h2><small>Letzte 100 Vorgänge</small></div>${table(['Zeit','Vorgang','Bereich','Eintrag'],db.audit.map(a=>`<tr><td>${esc(new Date(a.created_at).toLocaleString('de-AT'))}</td><td>${esc(a.action)}</td><td>${esc(({customers:'Kunden',contracts:'Verträge',claims:'Schäden',referrers:'Tippgeber',commissions:'Provisionen',settlements:'Abrechnungen',documents:'Dokumente',settings:'Einstellungen'})[a.entity]||a.entity)}</td><td>${a.entity_id||'—'}</td></tr>`))}</section>`;}
function field(name,label,value='',type='text',required=false){return `<label class="field"><span>${label}${required?' <b>*</b>':''}</span><input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'autocomplete="'+(name==='current_password'?'current-password':'new-password')+'"':''} ${name==='base'||name==='premium'||name==='rate'?'inputmode="decimal"':''}></label>`;}
function textarea(name,label,value=''){return `<label class="field full"><span>${label}</span><textarea name="${name}" rows="3">${esc(value)}</textarea></label>`;}
function select(name,label,options,value='',required=false){return `<label class="field ${!label?'compact':''}">${label?`<span>${label}${required?' <b>*</b>':''}</span>`:''}<select name="${name}" aria-label="${esc(label||'Status filtern')}" ${required?'required':''}>${options.map(([v,l])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`).join('')}</select></label>`;}
function fileDrop(accept='') {return `<label class="file-drop"><strong>Datei hierher ziehen</strong><span class="file-drop-name">Alternativ anklicken und eine Datei auswählen · maximal 20 MB</span><input type="file" name="file" ${accept?`accept="${esc(accept)}"`:''} required></label>`;}
function modal(title,body,kind,record={},submit='Speichern'){dialog.classList.remove('kfz-dialog');dialog.innerHTML=`<form id="editor" data-kind="${kind}" data-id="${record.id||''}" data-version="${record.version||''}"><div class="modal-head"><div class="eyebrow">AGENTUR CRM</div><h2>${title}</h2><button type="button" class="close" data-action="close" aria-label="Schließen">×</button></div><div class="modal-body">${body}<div class="form-error" role="alert"></div></div><div class="modal-footer"><button type="button" class="secondary" data-action="close">Abbrechen</button><button class="primary">${submit}</button></div></form>`;dialog.showModal();}
function editCustomer(c={}){const type=c.customer_type||'natural';const connection=!c.id&&db.customers.length?`<h3>Optionale Verbindung</h3>${customerPicker('','related_customer_id','Mit bestehendem Kunden oder Firma verbinden',false)}<div class="form-grid">${relationshipFields({},true)}</div><p class="hint">Die Verbindung wird beim Speichern gleichzeitig in beiden Kundenakten angelegt.</p>`:'';modal(c.id?'Kundenakte bearbeiten':'Neuen Kunden anlegen',`<div class="form-grid">${select('customer_type','Kundentyp',[['natural','Natürliche Person'],['legal','Juristische Person']],type,true)}${field('company','Firmenname',c.company,'text',type==='legal')}${field('first_name','Vorname / Kontaktperson',c.first_name,'text',type==='natural')}${field('last_name','Nachname / Kontaktperson',c.last_name,'text',type==='natural')}${field('birthday','Geburtsdatum',c.birthday,'date')}${field('email','E-Mail',c.email,'email')}${field('phone','Telefon',c.phone,'tel')}${field('address','Straße & Hausnummer',c.address)}${field('postal_code','Postleitzahl',c.postal_code)}${field('city','Ort',c.city)}${textarea('notes','Notizen',c.notes)}</div><p class="hint" id="customer-type-hint"></p>${connection}${c.id?`<label class="check"><input type="checkbox" name="archived" ${c.archived?'checked':''}> Kundenakte archivieren (Verträge bleiben erhalten)</label>`:''}`,'customers',c);updateCustomerType();if(!c.id&&db.customers.length){setupCustomerPicker('','related_customer_id','',false);updateRelationshipTemplate();}}
function updateCustomerType(){const f=document.querySelector('#editor');if(!f||f.dataset.kind!=='customers')return;const legal=f.elements.customer_type.value==='legal',company=f.elements.company,first=f.elements.first_name,last=f.elements.last_name,birthday=f.elements.birthday;company.required=legal;first.required=!legal;last.required=!legal;birthday.closest('label').hidden=legal;document.querySelector('#customer-type-hint').textContent=legal?'Der Firmenname ist erforderlich. Vor- und Nachname können als optionale Kontaktperson erfasst werden.':'Vor- und Nachname sind erforderlich. Eine Firma kann zusätzlich hinterlegt werden.';}
function editReferrer(r={}){modal(r.id?'Tippgeber bearbeiten':'Tippgeber anlegen',`<div class="form-grid">${field('name','Name / Firma',r.name,'text',true)}${field('rate','Standard-Provisionssatz (%)',dec(r.rate_bp),'text',true)}${field('email','E-Mail',r.email,'email')}${field('phone','Telefon',r.phone,'tel')}${field('iban','IBAN',r.iban)}${textarea('address','Anschrift',r.address)}${textarea('notes','Vereinbarung / Notizen',r.notes)}</div><p class="hint">Der Standardsatz wird bei der Zuordnung zu einem Vertrag übernommen. Bestehende Verträge und Buchungen werden bei Änderungen nicht neu berechnet.</p>${r.id?`<label class="check"><input type="checkbox" name="archived" ${r.archived?'checked':''}> Tippgeber archivieren</label>`:''}`,'referrers',r);}
function customerPicker(id,name='customer_id',label='Kunde',required=true){
 const c=customer(id);
 return `<div class="field customer-picker" data-required="${required?'1':'0'}"><label for="customer-search">${esc(label)}${required?' <b>*</b>':''}</label><input type="hidden" name="${esc(name)}" value="${c?c.id:''}"><div class="customer-control"><input id="customer-search" type="text" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="customer-options" aria-describedby="customer-search-hint" autocomplete="off" ${required?'required':''} placeholder="Kunde suchen oder auswählen" value="${esc(c?full(c):'')}"><button type="button" class="customer-toggle" aria-label="Kundenliste öffnen" tabindex="-1">▾</button></div><div id="customer-options" class="customer-options" role="listbox" aria-label="Kunden" hidden></div><small id="customer-search-hint" class="hint">Name, Firma oder Kundennummer eingeben.</small><span class="sr-only" id="customer-results" role="status" aria-live="polite"></span></div>`;
}
function setupCustomerPicker(currentId,name='customer_id',excludeId='',required=true){
 const root=dialog.querySelector('.customer-picker'),input=root.querySelector('[role=combobox]'),value=root.querySelector(`[name="${name}"]`),list=root.querySelector('[role=listbox]'),toggle=root.querySelector('button');
 const customers=db.customers.filter(c=>(!c.archived||c.id===Number(currentId))&&c.id!==Number(excludeId));
 const normalize=s=>s.toLocaleLowerCase('de-AT').normalize('NFD').replace(/[\u0300-\u036f]/g,'');
 let matches=[],active=-1;
 function close(){list.hidden=true;input.setAttribute('aria-expanded','false');input.removeAttribute('aria-activedescendant');active=-1;}
 function highlight(index){active=index;list.querySelectorAll('[role=option]').forEach((el,i)=>{el.setAttribute('aria-selected',String(i===active));});if(active>=0){input.setAttribute('aria-activedescendant','customer-option-'+matches[active].id);list.children[active].scrollIntoView({block:'nearest'});}}
 function open(filter=''){
  matches=customers.filter(c=>normalize([full(c),c.company,'K-'+String(c.id).padStart(5,'0'),c.id].join(' ')).includes(normalize(filter.trim())));
  active=-1;input.removeAttribute('aria-activedescendant');
  list.innerHTML=matches.length?matches.map(c=>`<div id="customer-option-${c.id}" role="option" aria-selected="false" data-customer-id="${c.id}"><strong>${esc(full(c))}</strong><small>${esc(['K-'+String(c.id).padStart(5,'0'),c.company,c.city].filter(Boolean).join(' · '))}</small></div>`).join(''):'<div class="customer-no-results">Keine passenden Kunden gefunden.</div>';
  list.hidden=false;input.setAttribute('aria-expanded','true');root.querySelector('#customer-results').textContent=matches.length+' Kunden gefunden.';
 }
 function choose(id){const c=customers.find(c=>c.id===Number(id));if(!c)return;value.value=String(c.id);input.value=full(c);input.setCustomValidity('');value.dispatchEvent(new Event('change',{bubbles:true}));close();input.focus();close();}
 input.setCustomValidity(value.value||!required?'':'Bitte einen Kunden aus der Liste auswählen.');
 input.addEventListener('input',()=>{value.value='';input.setCustomValidity(input.value.trim()||required?'Bitte einen Kunden aus der Liste auswählen.':'');open(input.value);});
 input.addEventListener('focus',()=>open(value.value?'':input.value));
 input.addEventListener('click',()=>{if(list.hidden)open(value.value?'':input.value);});
 input.addEventListener('keydown',e=>{
  if(e.isComposing)return;
  if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(list.hidden)open(value.value?'':input.value);if(matches.length)highlight(active<0?(e.key==='ArrowDown'?0:matches.length-1):(active+(e.key==='ArrowDown'?1:-1)+matches.length)%matches.length);}
  else if(e.key==='Enter'&&!list.hidden){e.preventDefault();if(active>=0)choose(matches[active].id);}
  else if(e.key==='Escape'&&!list.hidden){e.preventDefault();e.stopPropagation();close();}
  else if(e.key==='Tab')close();
 });
 toggle.addEventListener('pointerdown',e=>e.preventDefault());
 toggle.addEventListener('click',()=>{const wasOpen=!list.hidden;input.focus();if(wasOpen)close();else open('');});
 list.addEventListener('pointerdown',e=>e.preventDefault());
 list.addEventListener('click',e=>{const option=e.target.closest('[data-customer-id]');if(option)choose(option.dataset.customerId);});
 root.addEventListener('focusout',e=>{if(!root.contains(e.relatedTarget))close();});
}
function editContract(c={},cid=''){if(c.id&&isKfzLine(c.line))return editKfzContract(c,cid);if(!db.customers.length){notice('Lege zuerst einen Kunden an.');return;}modal(c.id?'Versicherungsvertrag bearbeiten':'Versicherungsvertrag anlegen',`<div class="form-grid">${customerPicker(c.customer_id||cid)}${field('insurer','Versicherungsgesellschaft',c.insurer,'text',true)}${field('policy_number','Polizzennummer / vorläufige Nummer',c.policy_number,'text',true)}${field('line','Sparte (z. B. Haushalt, Kfz)',c.line,'text',true)}${select('ownership','Vertragsherkunft',[['Eigen','Eigen – durch meine Agentur abgeschlossen'],['Fremd','Fremd – andere Agentur oder Vermittler']],c.ownership||'Eigen',true)}${select('status','Status',['Beantragt','Aktiv','Gekündigt','Storniert','Abgelaufen'].map(x=>[x,x]),c.status||'Aktiv')}${field('start_date','Versicherungsbeginn',c.start_date||today(),'date',true)}${field('end_date','Vertragsende',c.end_date,'date')}${field('notice_date','Letzter Tag für Kündigung',c.notice_date,'date')}</div><h3>Prämie</h3><div class="form-grid">${field('premium','Prämie je Zahlung (€)',dec(c.premium_basis==='net'?c.premium_cents-(c.tax_cents||0):c.premium_cents),'text',true)}${select('premium_basis','Eingegebene Prämie', [['gross','Brutto – inklusive aller Steuerbestandteile'],['net','Netto – zuzüglich aller Steuerbestandteile']],c.premium_basis||'gross')}${select('frequency','Zahlungsrhythmus',[[12,'Monatlich'],[4,'Vierteljährlich'],[2,'Halbjährlich'],[1,'Jährlich']],c.frequency||12)}</div><div class="form-grid">${select('tax_mode','Versicherungssteuer', [['auto','Automatisch nach Sparte (Österreich)'],['manual_rate','Manueller Steuersatz (%)'],['manual_amount','Manueller Steuerbetrag (€)'],...(c.id?[['legacy','Bisheriger Betrag – Steuer nicht aufgeschlüsselt']]:[])],c.tax_mode||(c.id?'legacy':'auto'))}${field('tax_rate','Steuersatz (%)',dec(c.tax_rate_bp))}${field('tax_amount','Versicherungssteuer je Zahlung (€)',c.insurance_tax_cents==null?(c.tax_cents==null?'':dec(c.tax_cents)):dec(c.insurance_tax_cents))}${select('life_tax_case','Steuerregel Lebens-/Invaliditätsversicherung',[['standard','Regelfall: 4 %'],['single_short','Kapitalversicherung: Einmalerlag und kurze Laufzeit (11 %)']],c.life_tax_case||'standard')}</div><p class="hint" id="tax-hint"></p><div class="calculation" id="premium-preview" aria-live="polite"></div><p class="hint">Netto = ohne Versicherungssteuer; Brutto = inklusive Versicherungssteuer. Bei Kfz werden weitere Steuerbestandteile gesondert erfasst. <a href="https://www.bmf.gv.at/themen/steuern/steuern-von-a-bis-z/versicherungssteuer/bemessungsgrundlage-steuersaetze.html" target="_blank" rel="noopener">BMF-Steuersätze</a>.</p><h3>Tippgeber-Vereinbarung</h3><div class="form-grid">${select('referrer_id','Tippgeber',[['','Kein Tippgeber'],...db.referrers.filter(r=>!r.archived||r.id===c.referrer_id).map(r=>[r.id,r.name])],c.referrer_id||'')}${select('commission_basis','Berechnungsbasis',[['agency','Eingegangene Agenturprovision'],['premium','Nettoprämie (ohne Versicherungssteuer)'],['fixed','Fixbetrag je Buchung']],c.commission_basis||'agency')}${field('rate','Vereinbarter Anteil (%)',dec(c.rate_bp),'text',true)}${textarea('notes','Vertrags- und Provisionsvereinbarung',c.notes)}</div><p class="hint">Neue Vereinbarungen gelten nur für künftige Buchungen. Bereits erfasste Provisionen bleiben unverändert. Bei Fixbetrag wird kein Prozentsatz angewendet.</p><h3>Vertragsdokumente</h3>${c.id?contractDocumentList(c.id):'<p class="hint">Speichere den Vertrag, um Polizzen, Anträge und weitere Unterlagen anzuhängen.</p>'}<button type="submit" name="open_documents" value="1" class="secondary">Speichern & Dokumente anhängen</button>`,'contracts',c);setupCustomerPicker(c.customer_id);const lineInput=document.querySelector('#editor').elements.line;lineInput.setAttribute('list','insurance-lines');lineInput.insertAdjacentHTML('afterend',`<datalist id="insurance-lines">${db.tax_rules.flatMap(r=>r.lines).map(line=>`<option value="${esc(line)}"></option>`).join('')}</datalist>`);updatePremium();}
function taxRate(line){const normalized=line.trim().toLowerCase();return db.tax_rules.find(r=>r.lines.some(name=>[name.toLowerCase(),name.toLowerCase()+'versicherung'].includes(normalized)))?.rate_bp??null;}
function updatePremium(){
 const f=document.querySelector('#editor');if(!f||f.dataset.kind!=='contracts')return;
 if(f.dataset.kfz==='1')return refreshKfzForm();
 if(isKfzLine(f.elements.line.value)){
  document.querySelector('#tax-hint').innerHTML='Für Kfz und Lkw gibt es eine eigene Vertragsanlage. <button type="button" class="secondary" data-action="switch-kfz">Zur Kfz-Vertragsanlage wechseln</button>';
  document.querySelector('#premium-preview').textContent='Fahrzeugklasse und alle Steuerbestandteile werden in der Kfz-Vertragsanlage erfasst.';
  f.elements.tax_mode.setCustomValidity('Bitte die Kfz-Vertragsanlage verwenden.');return;
 }
 const e=f.elements,mode=e.tax_mode.value,basis=e.premium_basis.value;
 const amount=parseCents(e.premium.value),standard=taxRate(e.line.value);
 e.tax_rate.readOnly=mode!=='manual_rate';e.tax_amount.readOnly=mode!=='manual_amount';
 e.tax_rate.required=mode==='manual_rate';e.tax_amount.required=mode==='manual_amount';
 e.life_tax_case.closest('label').hidden=mode!=='auto'||standard!==400;
 let bp=mode==='auto'?(standard===400&&e.life_tax_case.value==='single_short'?1100:standard):mode==='manual_rate'?parseCents(e.tax_rate.value):null;
 if(mode==='auto')e.tax_rate.value=bp===null?'':dec(bp);
 if(mode==='manual_amount'||mode==='legacy')e.tax_rate.value='';
 const hint=document.querySelector('#tax-hint');
 hint.textContent=mode==='legacy'?'Bestandsvertrag: Der bisherige Gesamtbetrag bleibt erhalten. Für eine Aufschlüsselung Automatik oder manuelle Eingabe wählen.':mode==='auto'&&bp===null?'Sparte nicht eindeutig zugeordnet. Bitte eine bekannte Sparte (z. B. Haushalt, Kfz, Krankenversicherung, Leben) oder manuelle Eingabe wählen. Pflanzen-/Hagelversicherungen benötigen eine Berechnung anhand der Versicherungssumme.':mode==='auto'&&standard===400?'Regelfall 4 %. Bei Kapitalversicherungen mit Einmalerlag gilt bei kurzer Laufzeit 11 %: unter 10 Jahren, wenn Versicherungsnehmer und versicherte Personen bei Abschluss mindestens 50 sind, sonst unter 15 Jahren. Steuerbefreiungen und abweichende Polizzen bitte manuell erfassen.':'Steuerbetrag gilt je Zahlung. Manuelle Werte bleiben auch bei einem Spartenwechsel erhalten.';
 let tax=mode==='manual_amount'?parseCents(e.tax_amount.value):null;
 if(amount!==null&&bp!==null&&bp<=10000){const divisor=basis==='net'?10000:10000+bp;tax=Number((BigInt(amount)*BigInt(bp)+BigInt(Math.floor(divisor/2)))/BigInt(divisor));}
 if(mode==='auto'||mode==='manual_rate')e.tax_amount.value=tax===null?'':dec(tax);
 if(mode==='legacy')e.tax_amount.value='';
 const valid=amount!==null&&(mode==='legacy'||(tax!==null&&(bp===null||bp<=10000)&&(basis==='net'||tax<=amount)));
 e.tax_mode.setCustomValidity(mode==='auto'&&bp===null?'Bitte die Sparte zuordnen oder die Steuer manuell eingeben.':'');
 const preview=document.querySelector('#premium-preview');
 if(!valid){preview.textContent='Bitte gültige Prämien- und Steuerangaben eingeben. Die Steuer darf die Bruttoprämie nicht überschreiten.';return;}
 if(mode==='legacy'){preview.textContent='Jahresprämie (bisheriger Gesamtbetrag): '+euro(amount*Number(e.frequency.value));return;}
 const gross=basis==='net'?amount+tax:amount,net=gross-tax,n=Number(e.frequency.value);
 preview.textContent=`Je Zahlung: Netto ${euro(net)} + Versicherungssteuer ${euro(tax)} = Brutto ${euro(gross)}. Jährlich: Brutto ${euro(gross*n)} (davon Steuer ${euro(tax*n)}).`;
}
function isKfzLine(line){return /kfz|kraftfahr|kasko|autohaftpflicht|lkw|nutzfahr|lieferwagen|pkw/i.test(line||'');}
function parseCents(v){if(!/^\d{1,10}([,.]\d{1,2})?$/.test(v.trim()))return null;const [a,b='']=v.trim().replace(',','.').split('.');return Number(a)*100+Number(b.padEnd(2,'0'));}
function newCommission(){const available=db.contracts.filter(c=>c.referrer_id&&c.status!=='Storniert'&&!referrer(c.referrer_id)?.archived);if(!available.length){notice('Lege zuerst einen Vertrag mit Tippgeber-Vereinbarung an.');return;}modal('Tippgeber-Provision buchen',`${select('contract_id','Versicherungsvertrag',available.map(c=>[c.id,c.policy_number+' · '+full(customer(c.customer_id))+' · '+c.insurer]),available[0].id,true)}<div class="form-grid">${field('booking_date','Buchungsdatum',today(),'date',true)}${select('kind','Provisionsart',['Abschluss','Folge','Sondervergütung'].map(x=>[x,x]),'Abschluss')}${select('premium_period','Prämienzeitraum',[['payment','Eine Prämienzahlung'],['year','Ein Versicherungsjahr']],'payment')}${field('base','Berechnungsbasis / Fixbetrag (€)','','text',true)}${field('reference','Eindeutige Buchungsreferenz','','text',true)}</div><div class="calculation" id="commission-preview"></div><p class="hint" id="commission-hint"></p>${textarea('memo','Beleg / Abrechnungszeitraum / Notizen')}<p class="hint">Die Referenz verhindert eine doppelte Erfassung desselben Belegs. Jede wiederkehrende Provision erhält eine eigene Referenz und Buchung.</p>`,'commissions',{},'Provision verbindlich buchen');updateCommission();}
function updateCommission(){
 const f=document.querySelector('#editor');if(!f||f.dataset.kind!=='commissions')return;
 const c=contract(f.elements.contract_id.value),premium=c.commission_basis==='premium',missing=premium&&c.tax_cents==null;
 const input=f.elements.base;
 f.elements.premium_period.closest('label').hidden=!premium;
 input.readOnly=premium;
 input.previousElementSibling.textContent=premium?'Nettoprämie als Berechnungsbasis (€)':'Berechnungsbasis / Fixbetrag (€)';
 if(f.dataset.previousContract!==String(c.id)){input.value='';f.dataset.previousContract=String(c.id);}
 if(premium)input.value=missing?'':dec((c.premium_cents-c.tax_cents)*(f.elements.premium_period.value==='year'?c.frequency:1));
 f.elements.contract_id.setCustomValidity(missing?'Bitte zuerst im Vertrag die Versicherungssteuer aufschlüsseln.':'');
 const base=parseCents(input.value),amount=base===null?null:c.commission_basis==='fixed'?base:Number((BigInt(base)*BigInt(c.rate_bp)+5000n)/10000n);
 document.querySelector('#commission-preview').textContent=`${referrer(c.referrer_id)?.name} · ${missing?'Nettoprämie noch nicht ermittelbar':amount===null?'Betrag eingeben':euro(amount)}${c.commission_basis!=='fixed'?' ('+dec(c.rate_bp)+' %)':''}`;
 document.querySelector('#commission-hint').textContent=missing?'Bitte zuerst den Vertrag bearbeiten und die Versicherungssteuer automatisch oder manuell erfassen.':premium?'Die Nettoprämie wird aus der gespeicherten Bruttoprämie abzüglich Versicherungssteuer übernommen. Je Zahlung: '+euro(c.premium_cents)+' − '+euro(c.tax_cents)+' = '+euro(c.premium_cents-c.tax_cents)+'. Der gewählte Prämienzeitraum bestimmt die Berechnungsbasis.':c.commission_basis==='agency'?'Gib die tatsächlich eingegangene Agenturprovision ein.':'Gib den vereinbarten Auszahlungsbetrag ein.';
}
function newSettlement(){if(!db.referrers.length){notice('Lege zuerst einen Tippgeber an.');return;}modal('Abrechnung erstellen',`${select('referrer_id','Tippgeber',db.referrers.map(r=>[r.id,r.name]),db.referrers[0].id,true)}<div class="form-grid">${field('period_start','Buchungen ab',today().slice(0,8)+'01','date',true)}${field('period_end','Buchungen bis',today(),'date',true)}</div><div class="calculation" id="settlement-preview"></div><p class="hint">Enthält alle offenen, nicht aufgehobenen Buchungen des gewählten Zeitraums. Der Beleg hält Beträge und Empfängerdaten fest; spätere Änderungen verändern ihn nicht. Keine automatische Überweisung. Steuerlicher Umsatzsteuerausweis ist nicht konfiguriert.</p>`,'settlements',{},'Abrechnung verbindlich erstellen');updateSettlement();}
function updateSettlement(){const f=document.querySelector('#editor');if(!f||f.dataset.kind!=='settlements')return;const rows=db.commissions.filter(m=>m.referrer_id===Number(f.elements.referrer_id.value)&&!m.voided&&!m.settlement_id&&m.booking_date>=f.elements.period_start.value&&m.booking_date<=f.elements.period_end.value);document.querySelector('#settlement-preview').textContent=`${rows.length} offene Buchungen · ${euro(rows.reduce((a,m)=>a+m.amount_cents,0))}`;}
function reverse(id){const m=db.commissions.find(x=>x.id===Number(id));modal(m.settlement_id?'Gegenbuchung erstellen':'Offene Provision aufheben',`<p>${esc(m.reference)} · <strong>${euro(m.amount_cents)}</strong></p><p>${m.settlement_id?'Die ursprüngliche Abrechnung bleibt bestehen. Eine negative Buchung wird für die nächste Abrechnung angelegt.':'Die Buchung bleibt im Protokoll sichtbar und wird nicht mehr abgerechnet.'}</p>${textarea('reason','Begründung (erforderlich)')}`,'commissions/reverse',m,m.settlement_id?'Gegenbuchung erstellen':'Provision aufheben');dialog.querySelector('textarea').required=true;}
function pay(id){const s=db.settlements.find(x=>x.id===Number(id));modal('Zahlung oder Ausgleich dokumentieren',`<p><strong>${esc(s.number)} · ${euro(s.total_cents)}</strong></p><p>Erfasse ausschließlich eine bereits erfolgte Zahlung oder Verrechnung. Es wird keine Überweisung ausgelöst.</p>${field('paid_at','Datum der Zahlung / Verrechnung',today(),'date',true)}${field('payment_reference','Zahlungs- oder Ausgleichsreferenz','','text',true)}`,'settlements/pay',s,'Als erledigt markieren');}
function contractDocumentList(id){
 const docs=db.documents.filter(d=>d.contract_id===Number(id)&&!d.claim_id);
 return docs.length?table(['Dateiname','Hinzugefügt','Größe',''],docs.map(d=>`<tr><td class="document-name">${esc(d.filename)}</td><td>${day(d.created_at)}</td><td>${Math.max(1,Math.ceil(d.size/1024))} KB</td><td class="row-actions">${documentActions(d)}</td></tr>`)):'<p class="hint">Noch keine Dokumente zu diesem Vertrag. Hier kannst du die digitale Polizze, Anträge und sonstige Unterlagen ablegen.</p>';
}
function upload(cid,contractId=''){
 const c=contractId?contract(contractId):null;
 if(contractId&&!c){notice('Vertrag nicht gefunden. Bitte neu laden.');return;}
 modal(c?'Dokumente zum Versicherungsvertrag':'Dokument ablegen',`<input type="hidden" name="customer_id" value="${esc(c?c.customer_id:cid)}">${c?`<input type="hidden" name="contract_id" value="${c.id}"><p><strong>${esc(c.policy_number)} · ${esc(c.insurer)}</strong><br>${esc(c.line)} · ${esc(full(customer(c.customer_id)))}</p>${contractDocumentList(c.id)}<h3>Dokument anhängen</h3>`:select('contract_id','Zuordnung',[['','Allgemeine Kundenakte'],...db.contracts.filter(c=>c.customer_id===Number(cid)).map(c=>[c.id,c.policy_number+' · '+c.line])])}${fileDrop()}<p class="hint">Polizze, Antrag oder sonstige Unterlage, z. B. als PDF, Bild, E-Mail oder Word-Datei. Jede Datei wird lokal gespeichert und in die Datensicherung aufgenommen. Du kannst nacheinander weitere Dokumente anhängen.</p>`,'documents',{},'Dokument anhängen');
 if(c)document.querySelector('#editor').dataset.contractId=String(c.id);
}
function renameDocument(id){
 const document=db.documents.find(item=>item.id===Number(id));
 if(!document){notice('Dokument nicht gefunden. Bitte neu laden.');return;}
 if(dialog.open)dialog.close();
 modal('Dokument umbenennen',`${field('filename','Dateiname inklusive Dateiendung',document.filename,'text',true)}<p class="hint">Nur der angezeigte Name und der Name beim Herunterladen werden geändert. Dateiinhalt und Zuordnung bleiben unverändert.</p>`,'documents/rename',document,'Dateinamen speichern');
 const form=document.querySelector('#editor');
 if(document.claim_id)form.dataset.claimId=String(document.claim_id);
 if(document.contract_id)form.dataset.contractId=String(document.contract_id);
}
async function downloadBackup(){const res=await fetch('/api/backup',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:'{}'});if(!res.ok){throw new Error((await res.json()).error);}const url=URL.createObjectURL(await res.blob()),a=document.createElement('a');a.href=url;a.download='CRM-Sicherung-'+today()+'.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notice('Sicherung erstellt. Bitte die heruntergeladene Datei getrennt aufbewahren.');}
function deleteRecordDetails(table,id){
 const source=({customers:db.customers,customer_relationships:db.customer_relationships,contracts:db.contracts,claims:db.claims,referrers:db.referrers,commissions:db.commissions,settlements:db.settlements,documents:db.documents,claim_emails:db.claim_emails})[table];
 const record=source?.find(row=>row.id===Number(id));if(!record)throw new Error('Eintrag nicht gefunden. Bitte neu laden.');
 const label=({customers:full(record),customer_relationships:'Diese Kundenverbindung',contracts:record.policy_number,claims:record.number,referrers:record.name,commissions:record.reference,settlements:record.number,documents:record.filename,claim_emails:record.subject||'E-Mail'})[table];
 let consequence='Dieser Datensatz wird dauerhaft gelöscht.';
 if(table==='customers')consequence='Der Kunde sowie zugehörige Dokumente und Kundenverbindungen werden dauerhaft gelöscht. Bestehende Verträge oder Schäden können das Löschen verhindern.';
 if(table==='contracts')consequence='Der Vertrag und seine zugehörigen Dokumente werden dauerhaft gelöscht. Bestehende Schäden oder Provisionsbuchungen können das Löschen verhindern.';
 if(table==='claims')consequence='Der Schaden sowie seine Dokumente und abgelegten E-Mails werden dauerhaft gelöscht.';
 if(table==='settlements')consequence='Die Abrechnung wird dauerhaft gelöscht. Zugeordnete Provisionen werden wieder als offen geführt.';
 return {label,consequence};
}
function confirmRemoveRecord(table,id){
 const {label,consequence}=deleteRecordDetails(table,id);
 if(dialog.open)dialog.close();
 dialog.classList.remove('kfz-dialog');
 dialog.innerHTML=`<div class="modal-head delete-confirm-head"><div class="eyebrow">SICHERHEITSABFRAGE</div><h2>Datensatz wirklich löschen?</h2><button type="button" class="close" data-action="close" aria-label="Warnfenster schließen">×</button></div><div class="modal-body delete-confirm-body"><div class="delete-warning-icon" aria-hidden="true">!</div><div><p><strong>${esc(label)}</strong></p><p>${esc(consequence)}</p><p class="delete-irreversible">Gelöschte Daten können nur aus einer Sicherung wiederhergestellt werden.</p></div></div><div class="modal-footer"><button type="button" class="secondary" data-action="close">Abbrechen</button><button type="button" class="primary danger-button" data-action="confirm-delete" data-table="${esc(table)}" data-id="${esc(id)}">Ja, endgültig löschen</button></div>`;
 dialog.showModal();
 dialog.querySelector('.modal-footer [data-action="close"]').focus();
}
async function removeRecord(table,id){
 deleteRecordDetails(table,id);
 const result=await api('records/delete',{table,id:Number(id)});
 if(dialog.open)dialog.close();
 if(selected&&Number(selected)===Number(id)&&((view==='customers'&&table==='customers')||(view==='claims'&&table==='claims')))selected=null;
 await reload();notice(result.warning||'Datensatz gelöscht.');
}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=b.dataset.id;try{switch(b.dataset.action){case'nav':view=id;query='';statusFilter='';selected=null;render();break;case'customer':view='customers';selected=id;render();break;case'claim-detail':view='claims';selected=id;render();break;case'back':selected=null;render();break;case'new-customer':editCustomer();break;case'edit-customer':editCustomer(customer(id));break;case'new-relationship':editRelationship({},id);break;case'edit-relationship':editRelationship(customerRelationship(id),selected);break;case'new-referrer':editReferrer();break;case'edit-referrer':editReferrer(referrer(id));break;case'new-contract':editContract({},id);break;case'new-kfz-contract':editKfzContract({},id);break;case'switch-kfz':{const draft=Object.fromEntries(new FormData(document.querySelector('#editor')));draft.rate_bp=parseCents(draft.rate)||0;dialog.close();editKfzContract(draft,draft.customer_id);break;}case'edit-contract':editContract(contract(id));break;case'new-claim':editClaim();break;case'new-claim-customer':editClaim({},id);break;case'new-claim-contract':editClaim({},'',id);break;case'edit-claim':editClaim(claim(id));break;case'claim-document':uploadClaimDocument(id);break;case'claim-email':addClaimEmail(id);break;case'new-commission':newCommission();break;case'new-settlement':newSettlement();break;case'reverse':reverse(id);break;case'pay':pay(id);break;case'upload':upload(id);break;case'contract-documents':upload('',id);break;case'rename-document':renameDocument(id);break;case'delete-record':confirmRemoveRecord(b.dataset.table,id);break;case'confirm-delete':b.disabled=true;await removeRecord(b.dataset.table,id);break;case'close':dialog.close();break;case'backup':b.disabled=true;await downloadBackup();b.disabled=false;break;case'logout':await api('logout',{});db=null;await init();break;case'retry':await init();break;}}catch(err){b.disabled=false;notice(err.message);}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const cursor=e.target.selectionStart;query=e.target.value;document.querySelector('#main').innerHTML=content();const input=document.querySelector('#search');input.focus();try{input.setSelectionRange(cursor,cursor);}catch(_){}return;}updateCustomerType();if(typeof updateImportCustomerType==='function')updateImportCustomerType();updatePremium();updateCommission();updateSettlement();});
document.addEventListener('change',e=>{if(e.target.name==='status-filter'){statusFilter=e.target.value;render();return;}const f=e.target.closest('#editor');if(f?.dataset.kind==='contracts'&&e.target.name==='referrer_id'){f.elements.rate.value=dec(referrer(e.target.value)?.rate_bp);}if(e.target.name==='relationship_template')updateRelationshipTemplate();updateCustomerType();if(typeof updateImportCustomerType==='function')updateImportCustomerType();updatePremium();updateCommission();updateSettlement();});
document.addEventListener('submit',async e=>{
 e.preventDefault();
 const f=e.target,submit=f.querySelector('button:not([type="button"]):last-child')||f.querySelector('.primary'),error=f.querySelector('.form-error');
 error.textContent='';submit.disabled=true;
 try{
  const openDocuments=e.submitter?.name==='open_documents';
  const d=Object.fromEntries(new FormData(f));
  if(f.id==='auth-form'){
   if(f.dataset.setup==='true'&&d.password!==d.confirmation)throw new Error('Die Passwörter stimmen nicht überein.');
   const r=await api(f.dataset.setup==='true'?'setup':'login',d);csrf=r.csrf;await reload();return;
  }
  if(f.id==='settings-form'){await api('settings',d);await reload();notice('Einstellungen gespeichert.');return;}
  if(f.id==='import-analyze'){await handleImportAnalyze(f);return;}
  if(f.dataset.kind==='imports/commit'){
   const r=await handleImportCommit(f);dialog.close();pendingImport=null;await reload();view=r.contract_id?'contracts':'customers';selected=r.contract_id?null:r.customer_id;render();
   notice((r.customer_created?'Kunde angelegt, ':'Kunde zugeordnet, ')+(r.contract_created?'Vertrag angelegt und Datei gespeichert.':r.contract_id?'Datei beim Vertrag gespeichert.':'Datei in der Kundenakte gespeichert.'));return;
  }
  if(f.dataset.id)d.id=Number(f.dataset.id);
  if(f.dataset.version)d.version=Number(f.dataset.version);
  if(['customers','referrers'].includes(f.dataset.kind))d.archived=f.elements.archived?.checked||false;
  if(f.dataset.kind==='documents'){
   const file=f.elements.file.files[0];
   if(!file||file.size>20*1024*1024)throw new Error('Bitte eine Datei mit maximal 20 MB wählen.');
   d.filename=file.name;
   d.data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Die Datei konnte nicht gelesen werden.'));reader.readAsDataURL(file);});
   delete d.file;
  }
  const r=await api(f.dataset.kind,d);
  dialog.close();await reload();
  if(f.dataset.kind==='contracts'&&openDocuments)upload('',r.id);
  else if(f.dataset.kind==='documents'&&f.dataset.claimId)uploadClaimDocument(f.dataset.claimId);
  else if(f.dataset.kind==='documents'&&f.dataset.contractId)upload('',f.dataset.contractId);
  else if(f.dataset.kind==='documents/rename'&&f.dataset.claimId)uploadClaimDocument(f.dataset.claimId);
  else if(f.dataset.kind==='documents/rename'&&f.dataset.contractId)upload('',f.dataset.contractId);
  else if(f.dataset.kind==='claims'){view='claims';selected=r.id;render();}
  notice(f.dataset.kind==='settlements'?'Abrechnung '+r.number+' erstellt.':f.dataset.kind==='claim-emails'?'E-Mail abgelegt.':f.dataset.kind==='documents/rename'?'Dateiname geändert.':'Gespeichert.');
 }catch(err){error.textContent=err.message;}finally{submit.disabled=false;}
});
init();
